def orangesRotting(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0]) if g else 0
    minutes = 0
    while True:
        new = []
        for i in range(R):
            for j in range(C):
                if g[i][j] == 1 and any(0 <= i + di < R and 0 <= j + dj < C and g[i + di][j + dj] == 2
                                        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    new.append((i, j))
        if not new:
            break
        for i, j in new:
            g[i][j] = 2
        minutes += 1
    return -1 if any(1 in row for row in g) else minutes

